17		// Rule 124: footer (tab bar + filter bar) is outside the viewport; subtract table header only
18		tableDataHeight := max(m.height-1, 1)
19		m.table.SetHeight(tableDataHeight)
20		m.table.SetColumns(m.calculateColumns())
21		// Force the Selected row style to width contentWidth so the selected background
22		// extends to the right viewport border, even when row content visually differs
