32	
33		rows := make([]table.Row, 0, len(m.entries))
34		for _, entry := range m.entries {
35			// Apply text search filter
36			if query != "" {
37				nameMatch := strings.Contains(strings.ToLower(entry.Name), query)
38				remoteMatch := strings.Contains(strings.ToLower(entry.GitRemote), query)
39				if !nameMatch && !remoteMatch {
40					continue
