64	
65		// bubbles does not clamp the cursor when the row count shrinks, so drilling
66		// into a smaller directory — or narrowing the filter — would leave it past
67		// the end. Nothing is highlighted then, and every action that resolves the
68		// selection (enter, ctrl+d, r, ctrl+s) silently does nothing.
69		if m.table.Cursor() >= len(rows) {
70			m.table.SetCursor(max(len(rows)-1, 0))
