89						return LoadErrorMsg{Error: err}
90					}
91					return EntriesLoadedMsg{Entries: []Entry{}}
92				}
93				return LoadErrorMsg{Error: err}
94			}
95	
96			dirEntries, err := os.ReadDir(targetDir)
97			if err != nil {
98				return LoadErrorMsg{Error: err}
99			}
100	
101			entries := make([]Entry, 0, len(dirEntries))
102			for _, dirEntry := range dirEntries {
103				// Skip hidden files/directories
104				if strings.HasPrefix(dirEntry.Name(), ".") {
105					continue
106				}
107	
108				info, err := dirEntry.Info()
109				if err != nil {
110					continue
111				}
112	
