1	package explorer
2	
3	import (
4		"sort"
5		"strings"
6		"time"
7	
8		"github.com/charmbracelet/bubbles/table"
9		tea "github.com/charmbracelet/bubbletea"
10	)
11	
12	// visibleItems returns the nodes the table is showing: the current level, sorted
13	// and filtered. Every action resolves the cursor through this, so the row the
14	// user is looking at is the row that gets acted on.
15	func (m *Model) visibleItems() []*TreeNode {
16		items := m.sortedItems(m.currentItems())
17		query := strings.ToLower(m.filterBar.SearchQuery())
18		if query == "" {
19			return items
20		}
21	
22		visible := make([]*TreeNode, 0, len(items))
23		for _, node := range items {
24			nameMatch := strings.Contains(strings.ToLower(node.Name), query)
25			pathMatch := strings.Contains(strings.ToLower(node.FullPath), query)
26			if nameMatch || pathMatch {
27				visible = append(visible, node)
28			}
29		}
30		return visible
31	}
32	
33	// updateTableRows rebuilds table rows from the visible items
34	func (m *Model) updateTableRows() {
35		items := m.visibleItems()
36		rows := make([]table.Row, 0, len(items))
37		for _, node := range items {
38			rows = append(rows, table.Row{
39				nodeTypeLabel(node),
40				node.Name,
41				nodeSlug(node.FullPath),
42				visibilityLabel(node),
43				node.AccessLevelName(),
44				timeAgo(node.CreatedAt),
45				timeAgo(node.LastActivityAt),
46				pipelineStatusLabel(node),
47			})
48		}
49		m.table.SetRows(rows)
50	
51		// bubbles does not clamp the cursor when the row count shrinks, so narrowing
52		// the filter would leave it past the end. Nothing is highlighted then, and
53		// every action that resolves the selection silently does nothing.
54		if m.table.Cursor() >= len(rows) {
55			m.table.SetCursor(max(len(rows)-1, 0))
56		}
57	
58		m.updateSortIndicators()
59	}
60	
61	// cycleSort cycles through sort options: each column asc then desc, then next column
62	func (m Model) cycleSort() (tea.Model, tea.Cmd) {
63		if m.sortAsc {
64			m.sortAsc = false
65		} else {
66			m.sortAsc = true
67			nextIdx := 0
68			for i, col := range sortableColumns {
69				if col == m.sortColumn {
70					nextIdx = (i + 1) % len(sortableColumns)
71					break
72				}
73			}
74			m.sortColumn = sortableColumns[nextIdx]
75		}
76		m.updateTableRows()
77		return m, nil
78	}
79	
80	// sortedItems returns nodes sorted by the current sort column and direction
81	func (m *Model) sortedItems(items []*TreeNode) []*TreeNode {
82		if len(items) == 0 {
83			return items
84		}
85	
86		sorted := make([]*TreeNode, len(items))
87		copy(sorted, items)
88	
89		sort.Slice(sorted, func(i, j int) bool {
90			a, b := sorted[i], sorted[j]
91	
92			var less bool
93			switch m.sortColumn {
94			case sortByName:
95				less = strings.ToLower(a.Name) < strings.ToLower(b.Name)
96			case sortByVisibility:
97				less = strings.ToLower(a.Visibility) < strings.ToLower(b.Visibility)
98			case sortByCreated:
99				less = timeBefore(a.CreatedAt, b.CreatedAt)
100			case sortByActivity:
101				less = timeBefore(a.LastActivityAt, b.LastActivityAt)
102			default: // sortByType
103				less = string(a.Type) < string(b.Type)
104			}
105	
106			if m.sortAsc {
107				return less
108			}
109			return !less
110		})
111	
112		return sorted
113	}
114	
115	// timeBefore compares two nullable times (nil is considered "oldest")
116	func timeBefore(a, b *time.Time) bool {
117		if a == nil && b == nil {
118			return false
119		}
120		if a == nil {
121			return true
122		}
123		if b == nil {
124			return false
125		}
126		return a.Before(*b)
127	}
128	
129	// updateSortIndicators updates column headers with ▲/▼ sort arrows
130	func (m *Model) updateSortIndicators() {
131		sortColIndex := map[sortField]int{
132			sortByType:       0,
133			sortByName:       1,
134			sortByVisibility: 3,
135			sortByCreated:    5,
136			sortByActivity:   6,
137		}
138		baseTitles := map[int]string{
