1	package components
2	
3	import (
4		"strings"
5	
6		"github.com/charmbracelet/bubbles/textinput"
7		tea "github.com/charmbracelet/bubbletea"
8		"github.com/charmbracelet/lipgloss"
9	
10		"github.com/anthnel/devdesk/internal/ui/theme"
11	)
12	
13	// FilterToken is a named toggle filter that can be active or inactive.
14	// Active tokens are shown as highlighted labels in the filter bar.
15	type FilterToken struct {
16		Label  string
17		Active bool
18	}
19	
20	// FilterBar is a single-line bar rendered at the bottom of a table viewport.
21	// It is hidden when no filter is active and appears automatically when:
22	//   - A toggle filter token is activated
23	//   - The user presses "/" to enter search mode
24	//
25	// Usage:
26	//
27	//	fb := components.NewFilterBar()
28	//	// or with toggle tokens:
29	//	fb := components.NewFilterBarWithTokens([]components.FilterToken{
30	//	    {Label: "tcp"}, {Label: "udp"},
31	//	})
32	//
33	// In resize: tableHeight := height - fb.ExtraHeight()
34	// In view:   append fb.View() as the last line after the table
35	// In update: forward keys to fb.Update(msg) when fb.InEditMode()
36	type FilterBar struct {
37		searching   bool
38		searchInput textinput.Model
39		searchQuery string
40		tokens      []FilterToken
41		width       int
42	}
43	
44	// NewFilterBar creates a FilterBar with no toggle tokens (text search only).
45	func NewFilterBar() FilterBar {
46		return newFilterBar(nil)
47	}
48	
49	// NewFilterBarWithTokens creates a FilterBar with the given toggle tokens.
50	func NewFilterBarWithTokens(tokens []FilterToken) FilterBar {
51		return newFilterBar(tokens)
52	}
53	
54	func newFilterBar(tokens []FilterToken) FilterBar {
55		si := textinput.New()
56		theme.StyleTextInput(&si)
57		si.CharLimit = 100
58	
59		fb := FilterBar{
60			searchInput: si,
61		}
62		if len(tokens) > 0 {
63			fb.tokens = make([]FilterToken, len(tokens))
64			copy(fb.tokens, tokens)
65		}
66		return fb
67	}
68	
69	// IsVisible returns true when the bar should be rendered (searching, query set, or any token active).
70	func (fb *FilterBar) IsVisible() bool {
71		if fb.searching || fb.searchQuery != "" {
72			return true
73		}
74		for _, t := range fb.tokens {
75			if t.Active {
76				return true
77			}
78		}
79		return false
80	}
81	
82	// ExtraHeight returns 2 when the bar is visible (1 separator + 1 bar), 0 otherwise.
83	// Subtract this from the table height so the bar doesn't overlap table rows.
84	func (fb *FilterBar) ExtraHeight() int {
85		if fb.IsVisible() {
86			return 2
87		}
88		return 0
89	}
90	
91	// Resize updates the display width used when rendering.
92	func (fb *FilterBar) Resize(width int) {
93		fb.width = width
94	}
95	
96	// InEditMode returns true when the search input is focused.
97	// Views must propagate this via their own InEditMode() to block command mode.
98	func (fb *FilterBar) InEditMode() bool {
99		return fb.searching
100	}
101	
102	// SearchQuery returns the current confirmed search string.
103	func (fb *FilterBar) SearchQuery() string {
104		return fb.searchQuery
105	}
106	
107	// ActivateSearch focuses the search input and returns the blink command.
108	func (fb *FilterBar) ActivateSearch() tea.Cmd {
109		fb.searching = true
110		fb.searchInput.Focus()
111		return textinput.Blink
112	}
113	
114	// ClearSearch clears the search query and blurs the input.
115	func (fb *FilterBar) ClearSearch() {
116		fb.searching = false
117		fb.searchQuery = ""
118		fb.searchInput.SetValue("")
119		fb.searchInput.Blur()
120	}
121	
122	// IsTokenActive returns true if the token with the given label is active.
123	func (fb *FilterBar) IsTokenActive(label string) bool {
124		for _, t := range fb.tokens {
125			if t.Label == label {
126				return t.Active
127			}
128		}
129		return false
130	}
